-- Zarnigaar: upgrade an EXISTING project with migrations 0001-0007 already applied. Cleans original sample fabric claims and enables reviews.

-- Generated by: node scripts/build-supabase-setup.mjs

-- Includes: 0008_remove_seed_fabric_claims.sql, 0009_product_reviews.sql

-- Run the ENTIRE file in Supabase SQL Editor as postgres.

-- Supabase CLI migration-history rows are not created by this bundle.

begin;

-- SOURCE: supabase/migrations/0008_remove_seed_fabric_claims.sql

-- Remove only the original sample fabric claims. Merchant-entered fabric_details,
-- care instructions and edited descriptions are preserved. Existing URLs stay valid.
update public.categories set description = 'Explore our clothing collection.'
where slug = 'clothing' and description = 'Lawn suits, co-ord sets and embroidered pieces.';

update public.categories set description = 'Explore our scarves.'
where slug = 'scarves' and description = 'Signature printed and woven scarves.';

update public.collections set name = 'Featured Styles'
where slug = 'luxury-lawn' and name = 'Luxury Lawn';
update public.collections set description = 'Explore featured articles.'
where slug = 'luxury-lawn' and description = 'Light, breezy, elegant lawn for every day.';

update public.products p set
  name = case when p.name = s.original_name then s.neutral_name else p.name end,
  description = case when p.description = s.original_description then '' else p.description end
from (values
  ('ZN-CL-001', 'embroidered-lawn-suit', 'Embroidered Lawn Suit', 'Suit 01', 'A three-piece embroidered lawn suit with delicate floral motifs, finished with a matching dupatta.'),
  ('ZN-CL-002', 'linen-co-ord-set', 'Linen Co-ord Set', 'Co-ord Set', 'A relaxed linen co-ord set tailored for effortless everyday elegance.'),
  ('ZN-CL-003', 'printed-lawn-suit', 'Printed Lawn Suit', 'Suit 02', 'Hand-finished printed lawn suit with contrast piping and a printed dupatta.'),
  ('ZN-CL-004', 'solid-lawn-suit', 'Solid Lawn Suit', 'Suit 03', 'A solid-tone lawn suit with subtle self-embroidery along the neckline.'),
  ('ZN-SC-001', 'signature-scarf', 'Signature Scarf', 'Scarf', 'Our signature printed scarf in lightweight silk-blend fabric.'),
  ('ZN-CL-005', 'embroidered-suit', 'Embroidered Suit', 'Suit 04', 'A statement embroidered suit in rich jewel tones for special occasions.'),
  ('ZN-DP-001', 'classic-woven-dupatta', 'Classic Woven Dupatta', 'Dupatta', 'A finely woven dupatta with jacquard border detailing.'),
  ('ZN-AC-001', 'embroidered-tote', 'Embroidered Tote', 'Tote Bag', 'A structured tote finished with hand embroidery, for everyday carry.')
) as s(sku, slug, original_name, neutral_name, original_description)
where p.sku = s.sku and p.slug = s.slug
  and (p.name = s.original_name or p.description = s.original_description);

update public.faqs set
  question = 'Where can I find fabric and care details?',
  answer = 'Fabric and care details appear on each product page when provided for that article. Contact us if you need more information.'
where question = 'Are your fabrics pre-shrunk?'
  and answer = 'Our lawn and cotton pieces are pre-washed; we still recommend following the care label for longevity.';

-- SOURCE: supabase/migrations/0009_product_reviews.sql

-- Real customer feedback: one review per signed-in account per product.
create table if not exists public.product_reviews (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products(id) on delete cascade,
  user_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,
  author_name text not null default 'Customer',
  rating smallint not null check (rating between 1 and 5),
  body text not null check (char_length(body) between 1 and 2000 and body ~ '[^[:space:]]'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (product_id, user_id)
);
create index if not exists product_reviews_product_date_idx
  on public.product_reviews(product_id, created_at desc, id desc);
create index if not exists product_reviews_user_idx on public.product_reviews(user_id);

-- Public names come from the account profile, never from a submitted email/name.
create or replace function public.set_review_author()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    select coalesce(nullif(left(btrim(full_name), 80), ''), 'Customer')
      into new.author_name from public.profiles where id = new.user_id;
    new.author_name = coalesce(new.author_name, 'Customer');
  end if;
  new.updated_at = now();
  return new;
end;
$$;
revoke all on function public.set_review_author() from public, anon, authenticated;
drop trigger if exists set_review_author on public.product_reviews;
create trigger set_review_author before insert or update on public.product_reviews
  for each row execute function public.set_review_author();

alter table public.product_reviews enable row level security;
drop policy if exists reviews_public_read on public.product_reviews;
create policy reviews_public_read on public.product_reviews for select to anon, authenticated
  using (exists (select 1 from public.products p where p.id = product_id and p.status = 'active'));
drop policy if exists reviews_owner_insert on public.product_reviews;
create policy reviews_owner_insert on public.product_reviews for insert to authenticated
  with check ((select auth.uid()) = user_id and exists (
    select 1 from public.products p where p.id = product_id and p.status = 'active'
  ));
drop policy if exists reviews_owner_update on public.product_reviews;
create policy reviews_owner_update on public.product_reviews for update to authenticated
  using ((select auth.uid()) = user_id)
  with check ((select auth.uid()) = user_id and exists (
    select 1 from public.products p where p.id = product_id and p.status = 'active'
  ));
drop policy if exists reviews_owner_delete on public.product_reviews;
create policy reviews_owner_delete on public.product_reviews for delete to authenticated
  using ((select auth.uid()) = user_id or public.is_admin());

revoke all privileges on public.product_reviews from public, anon, authenticated;
grant select on public.product_reviews to anon, authenticated;
grant insert (product_id, rating, body) on public.product_reviews to authenticated;
grant update (rating, body) on public.product_reviews to authenticated;
grant delete on public.product_reviews to authenticated;
grant all privileges on public.product_reviews to service_role;

-- Batch averages/counts for product cards without exposing private profile data.
create or replace view public.product_rating_summaries with (security_invoker = true) as
  select product_id, round(avg(rating), 2) as average_rating, count(*)::integer as review_count
  from public.product_reviews group by product_id;
revoke all privileges on public.product_rating_summaries from public, anon, authenticated;
grant select on public.product_rating_summaries to anon, authenticated, service_role;
notify pgrst, 'reload schema';

commit;
